<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function fee_json(int $status,array $body):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($body,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())fee_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))fee_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$role=(string)$_SESSION['role'];$allowed=['admin','director','sub_director','headteacher','bursar'];if(!in_array($role,$allowed,true))fee_json(403,['ok'=>false,'message'=>'Your role cannot reverse school-fee entries.']);if($_SERVER['REQUEST_METHOD']!=='POST')fee_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))fee_json(400,['ok'=>false,'message'=>'Your session expired. Refresh the page and try again.']);
$db=db();$uid=(int)$_SESSION['user_id'];$school=filter_var($_POST['school_id']??null,FILTER_VALIDATE_INT);$entryId=filter_var($_POST['ledger_id']??null,FILTER_VALIDATE_INT);$reason=trim((string)($_POST['reason']??''));if(!$school||!$entryId||$reason===''||mb_strlen($reason)>255)fee_json(422,['ok'=>false,'message'=>'Choose an entry and enter a reversal reason of up to 255 characters.']);$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())fee_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
try{$db->beginTransaction();$q=$db->prepare('SELECT * FROM school_fee_ledger WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$entryId,$school]);$entry=$q->fetch();if(!$entry||!in_array($entry['entry_type'],['charge','payment','discount'],true))throw new DomainException('Only original charges, payments, and discounts can be reversed.');$q=$db->prepare('SELECT id FROM school_fee_ledger WHERE reversal_of=?');$q->execute([$entryId]);if($q->fetchColumn())throw new DomainException('This fee entry has already been reversed.');$type=match($entry['entry_type']){'payment'=>'payment_reversal','discount'=>'discount_reversal',default=>'charge_reversal'};$description=mb_substr('Reversal: '.$entry['description'],0,180);$reference=trim((string)$entry['reference']);$q=$db->prepare('INSERT INTO school_fee_ledger(school_id,pupil_id,entry_type,academic_year,term,description,amount,payment_method,reference,reversal_of,reversal_reason,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$school,$entry['pupil_id'],$type,$entry['academic_year'],$entry['term'],$description,$entry['amount'],$entry['payment_method'],$reference?:null,$entryId,$reason,$uid]);$reversalId=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$type,'school_fee_ledger',$reversalId,json_encode(['school_id'=>$school,'reversed_entry_id'=>$entryId,'reason'=>$reason,'amount'=>(float)$entry['amount']],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);$db->commit();
    $q=$db->prepare('SELECT l.*,u.name recorder FROM school_fee_ledger l JOIN users u ON u.id=l.recorded_by WHERE l.id=? AND l.school_id=?');$q->execute([$reversalId,$school]);$reversal=$q->fetch();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) balance FROM school_fee_ledger WHERE school_id=? AND pupil_id=?");$q->execute([$school,$entry['pupil_id']]);$balance=(float)$q->fetchColumn();$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','discount_reversal') THEN amount WHEN entry_type IN ('charge_reversal','discount') THEN -amount ELSE 0 END),0) charges,COALESCE(SUM(CASE WHEN entry_type='payment' THEN amount WHEN entry_type='payment_reversal' THEN -amount ELSE 0 END),0) payments FROM school_fee_ledger WHERE school_id=?");$q->execute([$school]);$totals=$q->fetch();fee_json(200,['ok'=>true,'message'=>'Fee entry reversed. The original transaction remains in the ledger.','data'=>['reversal'=>$reversal,'reversed_entry_id'=>$entryId,'balance'=>$balance,'charges'=>(float)$totals['charges'],'payments'=>(float)$totals['payments'],'outstanding'=>(float)$totals['charges']-(float)$totals['payments']]]);
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();fee_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();error_log('Fee reversal database error: '.$e->getMessage());fee_json($e->getCode()==='23000'?409:500,['ok'=>false,'message'=>'This fee entry could not be reversed. Check the fee-reversal migration and retry.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Fee reversal request error: '.$e->getMessage());fee_json(500,['ok'=>false,'message'=>'The fee reversal could not be completed.']);}
